changeSet.sql:
DELETE srp FROM stretchy_report_parameter srp JOIN stretchy_report sr ON sr.id = srp.report_id WHERE sr.report_name = 'Multi-tranche eligibility';
INSERT INTO stretchy_report_parameter (report_id, parameter_id, report_parameter_name) SELECT sr.id, sp.id, 'officeId' FROM stretchy_report sr JOIN stretchy_parameter sp ON sp.parameter_name = 'OfficeIdSelectOne' WHERE sr.report_name = 'Multi-tranche eligibility';
INSERT INTO stretchy_report_parameter (report_id, parameter_id, report_parameter_name) SELECT sr.id, sp.id, 'loanOfficerId' FROM stretchy_report sr JOIN stretchy_parameter sp ON sp.parameter_name = 'loanOfficerIdSelectAll' WHERE sr.report_name = 'Multi-tranche eligibility';
INSERT INTO stretchy_report_parameter (report_id, parameter_id, report_parameter_name) SELECT sr.id, sp.id, 'loanProductId' FROM stretchy_report sr JOIN stretchy_parameter sp ON sp.parameter_name = 'loanProductIdSelectAllWithoutCurrency' WHERE sr.report_name = 'Multi-tranche eligibility';
INSERT INTO stretchy_report_parameter (report_id, parameter_id, report_parameter_name) SELECT sr.id, sp.id, 'loanStatusId' FROM stretchy_report sr JOIN stretchy_parameter sp ON sp.parameter_name = 'trancheLoanStatusSelectAll' WHERE sr.report_name = 'Multi-tranche eligibility';
INSERT INTO stretchy_report_parameter (report_id, parameter_id, report_parameter_name) SELECT sr.id, sp.id, 'trancheMilestoneStatusId' FROM stretchy_report sr JOIN stretchy_parameter sp ON sp.parameter_name = 'trancheMilestoneStatusSelectAll' WHERE sr.report_name = 'Multi-tranche eligibility';
